def shortest_path(graph, source, target):
    from heapq import heappush, heappop

    def dijkstra(graph, source, target):
        # Priority queue
        queue = [(0, source)]
        # Mapping for the current minimum distance to a node
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        # Mapping for the previous node on the shortest path to a node
        previous = {node: None for node in graph}

        while queue:
            current_distance, current_node = heappop(queue)
            # No need to explore further if we found a shorter path
            if current_distance > distances[current_node]:
                continue
            for neighbour, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbour]:
                    distances[neighbour] = distance
                    previous[neighbour] = current_node
                    heappush(queue, (distance, neighbour))

        # Reconstruct the path
        path = []
        while target:
            path.append(target)
            target = previous[target]
        path.reverse()

        # Return the shortest path and its length
        if distances[target] == float('inf'):
            return float('inf'), None
        return distances[target], path

    return dijkstra(graph, source, target)
