def shortest_path(graph, source, target):
    # If the target is the same as source, the distance is 0 and the path is the source itself.
    if source == target:
        return (0, [source])

    # Initialize the distance and path dictionaries
    distances = {node: float('inf') for node in graph}
    path = {node: None for node in graph}
    distances[source] = 0

    # Priority queue to store nodes to be explored, initialized with the source node.
    queue = deque([(0, source)])

    while queue:
        current_distance, current_node = queue.popleft()

        if current_node == target:
            # Reconstruct the path from the target to the source
            path_reversed = []
            while current_node is not None:
                path_reversed.append(current_node)
                current_node = path[current_node]
            return (distances[target], path_reversed[::-1])

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a shorter path is found, update the distance and store the current node as the predecessor
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                path[neighbor] = current_node
                queue.append((distance, neighbor))

    # If the target is unreachable, return infinity and None
    return (float('inf'), None)

