def shortest_path(graph, source, target):
    # If the source is the same as the target, the shortest path is trivially zero.
    if source == target:
        return 0, [target]

    # Initialize the distances and previous nodes
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    previous_nodes = {node: None for node in graph}

    # Priority queue (min-heap) to keep track of the nodes we need to check.
    from heapq import heappush, heappop
    from collections import deque
    queue = deque([(0, source)])

    while queue:
        current_distance, current_node = heappop(queue)

        # If we found the target, we can stop.
        if current_node == target:
            # Reconstruct the path
            path = deque()
            while current_node is not None:
                path.appendleft(current_node)
                current_node = previous_nodes[current_node]
            return current_distance, list(path)

        # If we have already determined the shortest distance to this node, we skip it.
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If we found a shorter path to the neighbor, update the distances and the path
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heappush(queue, (distance, neighbor))

    # If we exited the loop without finding the target, the target is unreachable.
    return float('inf'), None
