def shortest_path(graph, source, target):
    # Initialize the distance and path dictionaries
    distance = {node: float('inf') for node in graph}
    distance[source] = 0
    path = {}

    # Priority queue to store nodes to be explored, initially just the source
    from collections import defaultdict
    from heapq import heappush, heappop
    pq = [(0, source)]

    while pq:
        current_distance, current_node = heappop(pq)

        # If already found a shorter path to the current node, ignore it
        if current_distance > distance[current_node]:
            continue

        # Explore all neighbors
        for neighbor, weight in graph.get(current_node, []):
            distance_to_neighbor = current_distance + weight

            # Only consider this path if it's shorter
            if distance_to_neighbor < distance[neighbor]:
                distance[neighbor] = distance_to_neighbor
                path[neighbor] = [current_node, neighbor]
                # Push the neighbor to the priority queue with its new distance
                heappush(pq, (distance_to_neighbor, neighbor))

    # If there is a path to the target, return (distance, path)
    if distance[target] < float('inf'):
        return (distance[target], path[target])
    else:
        # If there is no path, return infinity and None
        return (float('inf'), None)

